defs.script:
/*  */
document.addEventListener('copy', function(e) {
   const selection = window.getSelection().toString();
   if (!selection) return;
   const formattedSelection = selection.replace(/ {2,}/g, '\n');
   e.clipboardData.setData('text/plain', formattedSelection);
   e.preventDefault();
});
function detecTSpanFont(tspanElement) {
   tspanElement.setAttribute("style", "font-family: 'A-Fake-Font-Name-123', sans-serif;");
   const fallbackWidth = tspanElement.getComputedTextLength();
   tspanElement.removeAttribute("style");
   for (const n of ["Noto Sans","Ubuntu","Cantarell","Inter","Roboto","Liberation Sans","DejaVu Sans","Arimo","Arial"]) {
      tspanElement.setAttribute("style", "font-family: " + n + ", monospace;");
      const nTestWidth = tspanElement.getComputedTextLength();
      tspanElement.setAttribute("style", "font-family: monospace;");
      const monoWidth = tspanElement.getComputedTextLength();
      tspanElement.removeAttribute("style");
      if (nTestWidth !== monoWidth) {
         return n;
      }
   }
   return "sans-serif";
}
function NN(r) {
   const f = detecTSpanFont(r);
   switch(f) {
      case "Noto Sans": return "LM";
      case "Ubuntu": return 35 / 37;
      case "Cantarell": return 7 / 8;
      case "Inter": return 3 / 4;
      case "Roboto": return 2 / 3;
      case "Liberation Sans":
      case "DejaVu Sans":
      case "Arimo":
      case "Arial":
      default: return 4 / 5;
   }
}
document.onreadystatechange = () => {if(document.readyState === "interactive") {
   const w = NN(document.querySelector("tspan"));
   if (typeof w === "string" || (CSS.supports("-moz-orient", "vertical") && navigator.userAgent.toLowerCase().includes("linux")) || CSS.supports("font: -apple-system-body")) return;
   document.getElementById("text-bg").setAttribute("width","100%");
   for (const t of document.querySelectorAll("text[filter]")) t.setAttribute("textLength",String((Math.round((parseInt(t.getAttribute("textLength"),10)) * 0.67) * w)));
  }
}
/*  */
